const WBN = { "Korea, Dem. People's Rep.": 'North Korea', 'Korea, Rep.': 'South Korea', 'Somalia, Fed. Rep.': 'Somalia', 'Congo, Dem. Rep.': 'DR Congo', 'Congo, Rep.': 'Republic of the Congo', 'Yemen, Rep.': 'Yemen', 'Egypt, Arab Rep.': 'Egypt', 'Iran, Islamic Rep.': 'Iran', 'Venezuela, RB': 'Venezuela', 'Gambia, The': 'The Gambia', 'Bahamas, The': 'The Bahamas', 'Lao PDR': 'Laos', 'Syrian Arab Republic': 'Syria', 'Russian Federation': 'Russia', 'Turkiye': 'Türkiye', 'West Bank and Gaza': 'Palestine', 'Micronesia, Fed. Sts.': 'Micronesia', 'Kyrgyz Republic': 'Kyrgyzstan', 'Slovak Republic': 'Slovakia', 'Viet Nam': 'Vietnam', "Cote d'Ivoire": "Côte d'Ivoire", 'Hong Kong SAR, China': 'Hong Kong', 'St. Lucia': 'Saint Lucia', 'St. Vincent and the Grenadines': 'Saint Vincent and the Grenadines', 'St. Kitts and Nevis': 'Saint Kitts and Nevis' };
