  return { scales: parseScales(v(sc)), kp3: kp3.slice(-56), kpNow, g: gScale(kpNow), wind: w && w[0] ? +w[0].proton_speed : null, bt: m && m[0] ? +m[0].bt : null, bz: m && m[0] ? +m[0].bz_gsm : null, flare: f && f[0] ? { now: f[0].current_class, max: f[0].max_class, at: utc(f[0].max_time) } : null, n: kp3.length };
