/* ---------- tracked sites (shared with Console + Dossier) ---------- */
export function getSites(seed = []) { const s = store.get('sites'); return Array.isArray(s) && s.length ? s : seed.map(x => ({ id: x.id, name: x.name, lat: x.lat, lon: x.lon, ref: true })); }
