export function snapshot(rows) { const s = { t: Date.now(), version: HZ.version, sites: rows, sources: Object.entries(FEEDS).map(([id, f]) => ({ id, name: f.name, org: f.org, home: f.home, lic: f.lic, st: STATUS[id] ? STATUS[id].st : 'idle', at: STATUS[id] ? STATUS[id].t : null })) }; store.set('snapshot', s); emit('hazards', { t: s.t, n: rows.length }); return s; }
